package com.whaa.shop.user.application;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.user.domain.UserAddress;import com.whaa.shop.user.infrastructure.UserAddressMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service public class AddressService {private final UserAddressMapper addresses;public AddressService(UserAddressMapper a){addresses=a;}public List<UserAddress> list(long uid){return addresses.selectList(new LambdaQueryWrapper<UserAddress>().eq(UserAddress::getUserId,uid).orderByDesc(UserAddress::getIsDefault).orderByDesc(UserAddress::getId));}
 @Transactional public UserAddress save(long uid,UserAddress a){validate(a);a.setUserId(uid);if(a.getIsDefault()==null)a.setIsDefault(false);if(Boolean.TRUE.equals(a.getIsDefault())||addresses.selectCount(new LambdaQueryWrapper<UserAddress>().eq(UserAddress::getUserId,uid))==0){clearDefault(uid);a.setIsDefault(true);}if(a.getId()==null)addresses.insert(a);else{owned(uid,a.getId());addresses.updateById(a);}return a;}
 @Transactional public void defaultAddress(long uid,Long id){UserAddress a=owned(uid,id);clearDefault(uid);a.setIsDefault(true);addresses.updateById(a);}@Transactional public void delete(long uid,Long id){UserAddress a=owned(uid,id);addresses.deleteById(id);if(Boolean.TRUE.equals(a.getIsDefault())){List<UserAddress> rest=list(uid);if(!rest.isEmpty()){UserAddress first=rest.get(0);first.setIsDefault(true);addresses.updateById(first);}}}
 private void clearDefault(long uid){UserAddress patch=new UserAddress();patch.setIsDefault(false);addresses.update(patch,new LambdaQueryWrapper<UserAddress>().eq(UserAddress::getUserId,uid).eq(UserAddress::getIsDefault,true));}private UserAddress owned(long uid,Long id){UserAddress a=addresses.selectById(id);if(a==null||!a.getUserId().equals(uid))throw new BusinessException("收货地址不存在");return a;}private void validate(UserAddress a){if(a.getReceiverName()==null||a.getReceiverName().isBlank()||a.getPhone()==null||!a.getPhone().matches("^[0-9+ -]{6,20}$")||a.getDetail()==null||a.getDetail().isBlank())throw new BusinessException("请填写有效的收货人、联系电话和详细地址");}}
